/* ===========================================================================
   ABS.CLEAN LAYOUT & SIZING CONTROLS — START HERE
   Adjust these variables to fine-tune column widths, box sizes, character art,
   and circle icon.
   ========================================================================== */
body.theme-abs-clean {
    /* COLUMN & BOX WIDTHS (Left column widened so Link/Categories fit under Stats) */
    --abs-clean-left-col-width: clamp(310px, 30vw, 420px); /* Left column width */
    --abs-clean-box-max-width: 410px;     /* Maximum width of left-side boxes (progression, stats, links) */
    --abs-clean-side-col-offset-x: 0px;   /* Fine-tune sidebar horizontal position if needed (default: 0px) */
    --abs-clean-side-nudge: 10px;         /* Nudge Categories/Links boxes right, off the L-frame edge. */
    --abs-clean-outline-width: 1px;       /* Shared uniform stroke for the header/L contour. */
    --abs-clean-category-pill-text: var(--type-text, var(--theme-text, #dff6ff)); /* Categories pill text follows the active typing. */
    --abs-clean-header-surface:
        radial-gradient(ellipse 70% 90% at 50% 10%, var(--abs-clean-type-glow, rgba(56, 189, 248, 0.20)), transparent 70%),
        linear-gradient(135deg, rgba(6, 12, 22, 0.22), rgba(2, 4, 10, 0.30));
    /* CHARACTER NAME SIZE (decrease to keep long names on fewer lines) */
    --abs-clean-name-font-size: clamp(19px, 1.6vw, 26px);

    /* PORTRAIT ART CONTROLS */
    --abs-clean-art-top-shift: 5px;     /* Gap above the portrait stage (matches the Leader Skill rhythm); negative pulls it up over the header. */
    --abs-clean-art-offset-x: 0px;        /* Fine-tune the character portrait art X position. */
    --abs-clean-art-offset-y: 0px;      /* Fine-tune the portrait crop Y position (cover pan; negative raises the art). */
    --abs-clean-art-frame-height: 520px;  /* L-rail depth (auto-measured from the art; fallback). */
    --abs-clean-art-scale: 1;             /* Base portrait scale; the shared fill scale below handles undersized art. */
    --abs-clean-active-top-gap: 0px;      /* Extra clean-only gap above the full-width Active/Domain row. */
    --abs-clean-art-z-index: 40;          /* Portrait stacking depth. */
    --abs-clean-ui-scale: 0.80;           /* Overall abs.clean zoom: 0.80 = 20% more spacious (10% zoomed in from 0.70). */

    /* CIRCLE ICON CONTROLS — these are the only values to edit when tuning
       imported custom-card portraits. Main, Awakening, and Forms are kept
       independent so changing one area cannot resize the others. */
    --abs-clean-main-circle-size: 84px;   /* Main card circle diameter. */
    --abs-clean-circle-size: var(--abs-clean-main-circle-size, 84px);
    --abs-clean-main-circle-image-scale: 1.56; /* Main image zoom/crop. */
    --abs-clean-main-circle-image-position-x: 50%;
    --abs-clean-main-circle-image-position-y: 48%;

    --abs-clean-awakening-circle-size: 58px; /* Clean Awakening portrait diameter. */
    --abs-clean-awakening-image-scale: 1.56;    /* Awakening image zoom/crop. */
    --abs-clean-awakening-image-position-x: 50%;
    --abs-clean-awakening-image-position-y: 50%;
    --abs-clean-awakening-legacy-circle-size: 68px; /* Fallback/generated Awakening row diameter. */

    --abs-clean-form-circle-size: 68px;     /* Form portrait diameter. */
    --abs-clean-form-image-scale: 1.6;        /* Form image zoom/crop. */
    --abs-clean-form-image-position-x: 50%;
    --abs-clean-form-image-position-y: 50%;

    --abs-clean-circle-offset-x: 0px;     /* Fine-tune circle icon horizontal position. */
    --abs-clean-circle-offset-y: 0px;     /* Fine-tune circle icon vertical position. */
    --sba-lr-lightning-brightness: 1.5;    /* Keep the small LR lightning legible. */
    --sba-lr-lightning-contrast: 1.2;
}

/* ABS Clean header portrait: reuse the circular, type-coloured ring language
   from the cards view instead of the rectangular Dokkan card frame. */
body.theme-abs-clean #layout-abs-style #abs-composed-icon {
    grid-area: circle !important;
    --abs-clean-ring-color: var(--theme-border, #38bdf8);
    position: relative !important;
    isolation: isolate !important;
    width: var(--abs-clean-circle-size, 84px) !important;
    height: var(--abs-clean-circle-size, 84px) !important;
    min-width: var(--abs-clean-circle-size, 84px) !important;
    min-height: var(--abs-clean-circle-size, 84px) !important;
    flex-shrink: 0 !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    margin: 4px 0 0 0 !important;
    transform: translate(var(--abs-clean-circle-offset-x, 0px), var(--abs-clean-circle-offset-y, 0px)) !important;
    transform-origin: center center !important;
    overflow: visible !important;
}

body.theme-abs-clean #layout-abs-style #abs-composed-icon .card-frame,
body.theme-abs-clean #layout-abs-style #abs-composed-icon .lr-spin-dial,
body.theme-abs-clean #layout-abs-style #abs-composed-icon .lightning-overlay,
body.theme-abs-clean #layout-abs-style #abs-composed-icon .seza-lwf-border-canvas {
    display: none !important;
}

body.theme-abs-clean #layout-abs-style #abs-composed-icon .sba-lr-lwf-canvas {
    display: block !important;
    position: absolute !important;
    z-index: 1 !important;
    top: 50% !important;
    left: 50% !important;
    width: 170px !important;
    height: 280px !important;
    max-width: none !important;
    max-height: none !important;
    transform: translate(-50%, -50%) !important;
    transform-origin: 50% 50% !important;
    pointer-events: none !important;
    background: transparent !important;
    opacity: var(--sba-lr-aura-opacity, 1) !important;
    mix-blend-mode: screen !important;
    filter: grayscale(1) sepia(1) saturate(5) hue-rotate(var(--sba-lr-fx-hue, 0deg)) brightness(1.24) contrast(1.06) !important;
    -webkit-mask: radial-gradient(ellipse 65px 75px at 50% 50%, #000 0 55%, rgba(0, 0, 0, 0.92) 70%, rgba(0, 0, 0, 0.65) 85%, rgba(0, 0, 0, 0.2) 95%, transparent 100%) !important;
    mask: radial-gradient(ellipse 65px 75px at 50% 50%, #000 0 55%, rgba(0, 0, 0, 0.92) 70%, rgba(0, 0, 0, 0.65) 85%, rgba(0, 0, 0, 0.2) 95%, transparent 100%) !important;
}

body.theme-abs-clean #layout-abs-style #abs-composed-icon .sba-lr-lwf-lightning-canvas {
    z-index: 3 !important;
    top: 50% !important;
    left: 50% !important;
    transform: translate(-50%, -50%) !important;
    mix-blend-mode: screen !important;
    opacity: var(--sba-lr-lightning-opacity, 1) !important;
    filter: grayscale(1) sepia(1) saturate(6) hue-rotate(var(--sba-lr-fx-hue, 0deg)) brightness(var(--sba-lr-lightning-brightness, 1.5)) contrast(var(--sba-lr-lightning-contrast, 1.2)) !important;
}

body.theme-abs-clean #layout-abs-style #abs-composed-icon[data-card-type="str"] .sba-lr-lwf-canvas {
    mix-blend-mode: screen !important;
    filter: grayscale(1) sepia(1) saturate(12) hue-rotate(312deg) brightness(1.1) contrast(1.2) !important;
}

body.theme-abs-clean #layout-abs-style #abs-composed-icon[data-card-type="str"] .sba-lr-lwf-lightning-canvas {
    z-index: 3 !important;
    mix-blend-mode: screen !important;
    filter: grayscale(1) sepia(1) saturate(16) hue-rotate(312deg) brightness(1.35) contrast(1.4) !important;
}

body.theme-abs-clean #layout-abs-style #abs-composed-icon .sba-ring-effect {
    display: block !important;
    position: absolute !important;
    z-index: 6 !important;
    top: 50% !important;
    left: 50% !important;
    width: calc(100% + 4px) !important;
    height: calc(100% + 4px) !important;
    border-radius: 50% !important;
    clip-path: circle(50% at 50% 50%) !important;
    -webkit-mask-image: radial-gradient(circle closest-side, transparent 72%, #fff 84%, #fff 96%, transparent 100%) !important;
    mask-image: radial-gradient(circle closest-side, transparent 72%, #fff 84%, #fff 96%, transparent 100%) !important;
    -webkit-mask-repeat: no-repeat;
    mask-repeat: no-repeat;
    pointer-events: none !important;
    /* Keep the base transform overridable by the spinning keyframes. */
    transform: translate(-50%, -50%);
    transform-origin: center center !important;
    animation: abs-clean-ring-spin 8s linear infinite !important;
    mix-blend-mode: normal !important;
    opacity: 0.65 !important;
    will-change: transform, opacity !important;
    backface-visibility: hidden !important;
}

/* The mask uses the circle radius (not the square diagonal), exposing the
   electric arcs at 86%. Keep both the CSS and canvas FX in sync with settings. */
body.theme-abs-clean.fx-static #layout-abs-style #abs-composed-icon .sba-ring-effect,
body.theme-abs-clean.fx-no-seza #layout-abs-style #abs-composed-icon .sba-ring-effect[data-awakening-fx="seza"] {
    visibility: hidden !important;
    animation: none !important;
}

body.theme-abs-clean #layout-abs-style #abs-composed-icon .sba-ring-effect.sba-seza-ring-effect,
body.theme-abs-clean #layout-abs-style #abs-composed-icon .sba-ring-effect[data-awakening-fx="seza"] {
    background: conic-gradient(from 12deg, #c26bff, #ffca42, #5edfff, #ff69d6, #8aff87, #ffe869, #c26bff) !important;
    filter: saturate(1.40) brightness(1.20) contrast(1.15) !important;
}

body.theme-abs-clean #layout-abs-style #abs-composed-icon .sba-ring-effect.sba-eza-ring-effect,
body.theme-abs-clean #layout-abs-style #abs-composed-icon .sba-ring-effect[data-awakening-fx="eza"] {
    background: conic-gradient(from 12deg, #ffe033, #ff7700, #00d0ff, #ffea47, #ff6200, #00bfff, #ffe033) !important;
    filter: saturate(1.40) brightness(1.20) contrast(1.15) !important;
}

@keyframes abs-clean-ring-spin {
    from { transform: translate(-50%, -50%) rotate(0deg); }
    to { transform: translate(-50%, -50%) rotate(360deg); }
}

body.theme-abs-clean #layout-abs-style #abs-composed-icon::before {
    content: '';
    position: absolute !important;
    inset: 0 !important;
    z-index: 0 !important;
    border-radius: 50% !important;
    background: radial-gradient(circle at 50% 40%, rgba(15, 23, 42, 0.96), #020617 80%) !important;
    box-shadow: inset 0 -6px 12px rgba(2, 6, 23, 0.42) !important;
}

body.theme-abs-clean #layout-abs-style #abs-composed-icon::after {
    content: '';
    position: absolute !important;
    inset: 0 !important;
    z-index: 5 !important;
    box-sizing: border-box !important;
    border: 3.5px solid var(--abs-clean-ring-color) !important;
    border-radius: 50% !important;
    pointer-events: none !important;
    box-shadow:
        0 0 0 2.5px rgba(2, 6, 23, 0.94),
        0 0 14px color-mix(in srgb, var(--abs-clean-ring-color) 75%, transparent),
        inset 0 -8px 14px rgba(2, 6, 23, 0.34) !important;
    transition: opacity 0.25s ease, transform 0.25s ease !important;
}

body.theme-abs-clean #layout-abs-style #abs-composed-icon:has(.sba-seza-ring-effect)::after,
body.theme-abs-clean #layout-abs-style #abs-composed-icon:has([data-awakening-fx="seza"])::after {
    border-color: var(--abs-clean-ring-color) !important;
    box-shadow:
        0 0 0 2.5px rgba(2, 6, 23, 0.94),
        0 0 16px color-mix(in srgb, var(--abs-clean-ring-color) 70%, transparent),
        0 0 24px rgba(194, 107, 255, 0.55),
        inset 0 -8px 14px rgba(2, 6, 23, 0.34) !important;
}

body.theme-abs-clean #layout-abs-style #abs-composed-icon:has(.sba-eza-ring-effect)::after,
body.theme-abs-clean #layout-abs-style #abs-composed-icon:has([data-awakening-fx="eza"])::after {
    border-color: var(--abs-clean-ring-color) !important;
    box-shadow:
        0 0 0 2.5px rgba(2, 6, 23, 0.94),
        0 0 16px color-mix(in srgb, var(--abs-clean-ring-color) 70%, transparent),
        0 0 24px rgba(255, 202, 66, 0.55),
        inset 0 -8px 14px rgba(2, 6, 23, 0.34) !important;
}

body.theme-abs-clean #layout-abs-style #abs-composed-icon .thumb-box {
    position: absolute !important;
    inset: 3px !important;
    z-index: 2 !important;
    width: auto !important;
    height: auto !important;
    overflow: visible !important;
    border-radius: 50% !important;
    transform: none !important;
    background: transparent !important;
}

body.theme-abs-clean #layout-abs-style #abs-composed-icon .thumb-img {
    display: block !important;
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    object-position: center !important;
    transform: scale(1.36) !important;
    transform-origin: 50% 48% !important;
}

body.theme-abs-clean #layout-abs-style #abs-composed-icon .rarity-icon {
    display: none !important;
}

body.theme-abs-clean #layout-abs-style #abs-composed-icon .type-icon {
    display: none !important;
}

/* The hero itself is the identity focus; do not repeat rarity/type badges
   above it in the otherwise empty right header area. */
body.theme-abs-clean #layout-abs-style #abs-header-right-slot #abs-rarity-icon,
body.theme-abs-clean #layout-abs-style #abs-header-right-slot #abs-type-icon {
    display: none !important;
}

body.theme-abs-clean #layout-abs-style #abs-composed-icon .eza-icon {
    display: none !important;
}

/* The ability strip is a separate clean-only art-side rail. The passive panel
   keeps a text-only header; the rail is styled at the end of this file. */
body.theme-abs-clean #layout-abs-style #abs-clean-passive-icons {
    display: flex !important;
    align-items: center !important;
    width: fit-content !important;
    min-height: 0 !important;
    margin-top: 0 !important;
    padding: 0 !important;
    border: none !important;
    border-radius: 0 !important;
    background: transparent !important;
    box-shadow: none !important;
}

body.theme-abs-clean #layout-abs-style .abs-clean-name-line {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
    width: 100%;
}

body.theme-abs-clean #layout-abs-style #abs-clean-passive-icons[hidden] {
    display: none !important;
}

body.theme-abs-clean #layout-abs-style #abs-clean-passive-icons .abs-passive-icons-strip {
    display: grid !important;
    grid-auto-flow: column !important;
    grid-template-rows: repeat(5, 20px) !important;
    grid-auto-columns: 20px !important;
    gap: 2.5px !important;
    padding: 4px 5px !important;
    margin: 0 !important;
    background: linear-gradient(180deg, rgba(10, 16, 26, 0.94) 0%, rgba(4, 7, 14, 0.98) 100%) !important;
    border: 1px solid rgba(255, 255, 255, 0.14) !important;
    border-radius: 7px !important;
    box-shadow: 
        inset 0 2px 6px rgba(0, 0, 0, 0.85),
        inset 0 0 0 1px rgba(0, 0, 0, 0.6),
        inset 0 1px 0 rgba(255, 255, 255, 0.1),
        0 2px 6px rgba(0, 0, 0, 0.5) !important;
    max-height: 124px !important;
    box-sizing: border-box !important;
}

body.theme-abs-clean #layout-abs-style #abs-clean-passive-icons .abs-passive-ability-badge {
    width: 32px !important;
    height: 32px !important;
    padding: 2px !important;
    box-sizing: border-box !important;
    background: transparent !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    transition: transform 0.15s ease, opacity 0.15s ease !important;
}

body.theme-abs-clean #layout-abs-style #abs-clean-passive-icons .abs-passive-ability-badge:hover {
    transform: scale(1.3) translateY(-1px) !important;
    z-index: 100 !important;
    filter: brightness(1.2) !important;
}

body.theme-abs-clean #layout-abs-style #abs-clean-passive-icons .abs-passive-ability-badge img {
    width: 100% !important;
    height: 100% !important;
    object-fit: contain !important;
}

/* Typing glow on passive icons (clean side only). drop-shadow follows the
   icon's own alpha shape, so the baked-in green frame keeps its pixels. */
body.theme-abs-clean #layout-abs-style #abs-clean-passive-icons .abs-passive-ability-badge img {
    filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.8)) drop-shadow(0 0 6px var(--theme-border, #38bdf8)) !important;
}

/* ABS Clean hero composition: intentionally independent from the legacy
   two-column ABS grid. This mirrors the reference's left identity area and
   elevated, unboxed character art on the right. */

/* The matchup strip is moved directly under this root at runtime, so it is
   positioned against the full ABS Clean layout rather than the narrow identity
   header that contains the name and portrait. */


body.theme-abs-clean #layout-abs-style .abs-header-text {
    display: flex !important;
    flex-direction: column !important;
    justify-content: center !important;
    text-align: left !important;
    flex: 1 1 auto !important;
    min-width: 0 !important;
    position: relative !important;
}

body.theme-abs-clean #layout-abs-style #abs-char-name {
    width: max-content !important;
    max-width: 100% !important;
    font-size: var(--abs-clean-name-font-size, clamp(19px, 1.6vw, 26px)) !important;
    line-height: 1.15 !important;
    white-space: normal !important;
    word-break: normal !important;
    overflow-wrap: break-word !important;
    flex-shrink: 1 !important;
}

body.theme-abs-clean #layout-abs-style #abs-clean-release-date {
    display: inline-flex !important;
    align-items: center;
    flex-wrap: wrap;
    gap: 6px;
    margin-top: 10px !important;
    font-size: 13px;
    line-height: 1.3;
    color: #94a3b8;
    text-shadow: 0 1px 3px rgba(0, 0, 0, 0.85);
    cursor: default;
}

body.theme-abs-clean.editor-tool-page #layout-abs-style #abs-clean-release-date {
    cursor: pointer;
}

body.theme-abs-clean #layout-abs-style #abs-clean-release-date .abs-clean-date-item {
    display: inline-flex;
    align-items: baseline;
    gap: 5px;
}

body.theme-abs-clean #layout-abs-style #abs-clean-release-date .abs-clean-date-label {
    color: #7dd3fc;
    font-weight: 700;
    font-size: 12px;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    opacity: 0.85;
    line-height: normal;
}

body.theme-abs-clean #layout-abs-style #abs-clean-release-date .abs-clean-date-val {
    color: #f1f5f9;
    font-weight: 600;
    font-size: 12px;
    letter-spacing: 0.02em;
    line-height: normal;
}

body.theme-abs-clean #layout-abs-style #abs-clean-release-date .abs-clean-date-sep {
    color: #475569;
    font-weight: 700;
    margin: 0 3px;
    line-height: normal;
}

body.theme-abs-clean #layout-abs-style .abs-grid-container {
    position: relative !important;
    display: block !important;
    min-height: 820px;
}

body.theme-abs-clean #layout-abs-style .abs-main-col {
    display: flex !important;
    width: 54% !important;
    flex: 0 0 54% !important;
}

body.theme-abs-clean #layout-abs-style .abs-side-col {
    position: absolute !important;
    top: -228px !important;
    /* The left header has a restricted width for the hero art. Use the
       viewport instead, so this strip reaches the actual page-right edge. */
    left: calc(100vw - 84px) !important;
    right: auto !important;
    width: clamp(390px, 39vw, 620px) !important;
    z-index: 20 !important;
    overflow: visible !important;
    pointer-events: auto !important;
}

/* The hidden legacy art dock must not reserve space inside the new hero. */
body.theme-abs-clean #layout-abs-style .abs-side-col > :not(#abs-clean-portrait-stage):not(#abs-art-dock-wrapper) {
    position: relative;
    z-index: 3;
}

@media (max-width: 1050px) {
    body.theme-abs-clean #layout-abs-style .abs-top-header {
        min-height: 305px !important;
    }
    body.theme-abs-clean #layout-abs-style .abs-header-left {
        max-width: calc(100% - 180px) !important;
        width: auto !important;
    }
    body.theme-abs-clean #layout-abs-style .abs-main-col {
        width: 58% !important;
        flex-basis: 58% !important;
    }
    body.theme-abs-clean #layout-abs-style .abs-side-col {
        top: -210px !important;
        width: 45% !important;
    }
    body.theme-abs-clean #layout-abs-style #abs-clean-passive-icons {
        margin-top: 74px !important;
    }
}

/* ===========================================================================
   ABS.CLEAN PASSIVE CAPTION — FINAL PLACEMENT
   ===========================================================================
   Keep the section label above the panel like Categories. The generated
   passive name stays inside the panel, and the two information surfaces keep
   their mirrored top alignment.
*/
body.theme-abs-clean #layout-abs-style #abs-passive-skill-box {
    position: relative !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: stretch !important;
    box-sizing: border-box !important;
    margin-top: 30px !important;
    padding: 27px 10px 12px !important;
    overflow: visible !important;
    clip-path: none !important;
}

body.theme-abs-clean #layout-abs-style .abs-main-col > #abs-passive-skill-box {
    margin-top: 30px !important;
}

body.theme-abs-clean #layout-abs-style #abs-passive-skill-box > #abs-passive-name {
    position: absolute !important;
    top: calc(-30px + var(--abs-clean-passive-caption-shift, 0px)) !important;
    right: 0 !important;
    left: 0 !important;
    z-index: 10 !important;
    display: flex !important;
    align-items: center !important;
    justify-content: flex-start !important;
    text-align: left !important;
    width: 100% !important;
    max-width: none !important;
    min-width: 0 !important;
    height: 22px !important;
    min-height: 22px !important;
    margin: 0 !important;
    padding: 4px 10px !important;
    box-sizing: border-box !important;
    overflow: visible !important;
    background: color-mix(in srgb, var(--theme-border, #38bdf8) 14%, rgba(255, 255, 255, 0.08)) !important;
    background-image: none !important;
    border: 1px solid color-mix(in srgb, var(--theme-border, #38bdf8) 52%, transparent) !important;
    border-radius: 2px !important;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.18), 0 0 12px color-mix(in srgb, var(--theme-border, #38bdf8) 14%, transparent) !important;
    color: #ffffff !important;
    font: 900 9px/1 Arial, sans-serif !important;
    letter-spacing: 0.1em !important;
    text-transform: uppercase !important;
    white-space: nowrap !important;
    pointer-events: auto !important;
}

body.theme-abs-clean.theme-abs-clean-dark #layout-abs-style #abs-passive-skill-box > #abs-passive-name {
    background: color-mix(in srgb, var(--theme-border, #38bdf8) 16%, rgba(3, 8, 14, 0.42)) !important;
}

body.theme-abs-clean #layout-abs-style #abs-passive-skill-box > #abs-passive-name::after {
    content: none !important;
    display: none !important;
}

body.theme-abs-clean #layout-abs-style #abs-passive-skill-box > #abs-passive-name .abs-passive-header-title {
    position: relative !important;
    display: flex !important;
    align-items: center !important;
    justify-content: flex-start !important;
    text-align: left !important;
    width: 100% !important;
